Map<String, Long> unsorted = Map.of("NEFT", 7L, "UPI", 5L, "RTGS", 3L, "IMPS", 4L);

// Sort by KEY ascending:
Map<String, Long> byKey = unsorted.entrySet().stream()
    .sorted(Map.Entry.comparingByKey())
    .collect(Collectors.toMap(
        Map.Entry::getKey, Map.Entry::getValue,
        (e1, e2) -> e1,        // merge function (needed by toMap)
        LinkedHashMap::new));   // CRITICAL: preserves sorted order!
// {IMPS=4, NEFT=7, RTGS=3, UPI=5}  — alphabetical keys

// Sort by VALUE descending:
Map<String, Long> byValue = unsorted.entrySet().stream()
    .sorted(Map.Entry.<String, Long>comparingByValue().reversed())
    .collect(Collectors.toMap(
        Map.Entry::getKey, Map.Entry::getValue,
        (e1, e2) -> e1,
        LinkedHashMap::new));
// {NEFT=7, UPI=5, IMPS=4, RTGS=3}  — highest value first

// ❌ WITHOUT LinkedHashMap — order LOST:
Map<String, Long> broken = unsorted.entrySet().stream()
    .sorted(Map.Entry.comparingByKey())
    .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
// HashMap: {UPI=5, RTGS=3, NEFT=7, IMPS=4}  — RANDOM order!
