package com.bank.sortedmap.service;

import com.bank.sortedmap.dto.SortedMapResult;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.stream.Collectors;

@Service
@Slf4j
public class MapSortingService {

    public SortedMapResult sortMap() {
        Map<String, Long> original = new HashMap<>();
        original.put("NEFT", 7L);
        original.put("UPI", 5L);
        original.put("RTGS", 3L);
        original.put("IMPS", 4L);

        // Sort by KEY ascending → LinkedHashMap
        Map<String, Long> byKey = original.entrySet().stream()
            .sorted(Map.Entry.comparingByKey())
            .collect(Collectors.toMap(
                Map.Entry::getKey, Map.Entry::getValue,
                (e1, e2) -> e1,
                LinkedHashMap::new));

        // Sort by VALUE descending → LinkedHashMap
        Map<String, Long> byValue = original.entrySet().stream()
            .sorted(Map.Entry.<String, Long>comparingByValue().reversed())
            .collect(Collectors.toMap(
                Map.Entry::getKey, Map.Entry::getValue,
                (e1, e2) -> e1,
                LinkedHashMap::new));

        log.info("By key: {}", byKey);
        log.info("By value desc: {}", byValue);

        return new SortedMapResult(original, byKey, byValue,
            "LinkedHashMap preserves insertion order = sorted order. " +
            "HashMap randomizes order → sorted result is lost.");
    }
}
