package com.bank.sortedmap.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.Collectors;
import static org.assertj.core.api.Assertions.*;

class SortMapTest {

    @Test
    void sortByKeyAscending() {
        Map<String, Integer> sorted = Map.of("C", 3, "A", 1, "B", 2).entrySet().stream()
            .sorted(Map.Entry.comparingByKey())
            .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue,
                (a, b) -> a, LinkedHashMap::new));
        assertThat(new ArrayList<>(sorted.keySet())).containsExactly("A", "B", "C");
    }

    @Test
    void sortByValueDescending() {
        Map<String, Integer> sorted = Map.of("X", 1, "Y", 3, "Z", 2).entrySet().stream()
            .sorted(Map.Entry.<String, Integer>comparingByValue().reversed())
            .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue,
                (a, b) -> a, LinkedHashMap::new));
        assertThat(new ArrayList<>(sorted.keySet())).containsExactly("Y", "Z", "X");
    }

    @Test
    void hashMapLosesSortedOrder() {
        // Collect into HashMap (default) — order NOT preserved
        Map<String, Integer> hashMap = Map.of("C", 3, "A", 1, "B", 2).entrySet().stream()
            .sorted(Map.Entry.comparingByKey())
            .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
        // hashMap iteration order is UNPREDICTABLE — might not be A,B,C!
        // We can't assert order because HashMap is random
        assertThat(hashMap).hasSize(3);  // data is there, order is not
    }

    @Test
    void linkedHashMapPreservesSortedOrder() {
        Map<String, Integer> linked = Map.of("C", 3, "A", 1, "B", 2).entrySet().stream()
            .sorted(Map.Entry.comparingByKey())
            .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue,
                (a, b) -> a, LinkedHashMap::new));
        // LinkedHashMap: insertion order = sorted order
        List<String> keys = new ArrayList<>(linked.keySet());
        assertThat(keys).containsExactly("A", "B", "C");  // GUARANTEED order!
    }
}
